	private void blankNodeGraph(RepositoryConnection conn) {
		Resource graph = conn.getValueFactory().createBNode("graph");
		conn.add(iri(conn, "a"), iri(conn, "p"), iri(conn, "o"), graph);
		assertThat(rows(conn, "SELECT ?g { GRAPH ?g {} }"))
				.extracting(bs -> bs.getValue("g"))
				.containsExactly(graph);
		TupleQuery query = conn.prepareTupleQuery(PREFIX + "SELECT ?s { GRAPH ?g { ?s :p :o } }");
		query.setBinding("g", graph);
		assertThat(QueryResults.asList(query.evaluate())).extracting(bs -> bs.getValue("s"))
				.containsExactly(iri(conn, "a"));
	}

	private void defaultAliases(RepositoryConnection conn) {
		for (IRI alias : List.of(RDF4J.NIL, SESAME.NIL)) {
			assertThat(rows(conn, "SELECT * { GRAPH <" + alias + "> {} }")).hasSize(1);
			assertThat(rows(conn, "SELECT ?g { GRAPH ?g {} }")).isEmpty();
			conn.add(iri(conn, "a"), iri(conn, "p"), iri(conn, "o"));
			assertThat(rows(conn, "SELECT ?s { GRAPH <" + alias + "> { ?s :p :o } }"))
					.extracting(bs -> bs.getValue("s"))
					.containsExactly(iri(conn, "a"));
			conn.clear();
		}
	}

